import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;import java.io.*;import java.nio.charset.StandardCharsets;class PublicExamplesTest{static void values(Object[]expected,Object[]actual){assertNotNull(actual);assertEquals(Arrays.stream(expected).map(TaskBinding::value).toList(),Arrays.stream(actual).map(TaskBinding::value).toList());}static Object[]select(Object[]input,java.util.function.Supplier<Object[]>call){Object[]refs=input.clone();var before=Arrays.stream(input).map(TaskBinding::value).toList();Object[]out=call.get();for(int i=0;i<input.length;i++)assertSame(refs[i],input[i]);assertEquals(before,Arrays.stream(input).map(TaskBinding::value).toList());return out;}@Test void stableNamesAndInclusiveCardRange(){Object a=TaskBinding.customer(1,"Beta","Z","M","0000000000000002"),b=TaskBinding.customer(2,"Alpha","A","M","0000000000000004"),c=TaskBinding.customer(3,"Alpha","A","M","0000000000000003");Object[]in=TaskBinding.array(a,c,b);values(new Object[]{c,b,a},select(in,()->TaskBinding.sorted(in)));values(new Object[]{a,c,b},select(in,()->TaskBinding.range(in,"0000000000000002","0000000000000004")));}}
